--- a/src/lib/libdwarf/dwarf_rnglists.c
+++ b/src/lib/libdwarf/dwarf_rnglists.c
@@ -523,7 +523,28 @@
     if (offsetentry_index >= con->rc_offset_entry_count) {
         return DW_DLV_NO_ENTRY;
     }
+    if (!con->rc_offsets_array) {
+        return DW_DLV_NO_ENTRY;
+    }
     offset_len = con->rc_offset_size;
+    if (!offset_len) {
+        return DW_DLV_NO_ENTRY;
+    }
+    {
+        Dwarf_Small *base = con->rc_offsets_array;
+        Dwarf_Small *end = con->rc_endaddr;
+        Dwarf_Unsigned byteoff = offsetentry_index * offset_len;
+
+        if (end <= base) {
+            return DW_DLV_NO_ENTRY;
+        }
+        if (byteoff > (Dwarf_Unsigned)(end - base)) {
+            return DW_DLV_NO_ENTRY;
+        }
+        if (offset_len > (Dwarf_Unsigned)(end - (base + byteoff))) {
+            return DW_DLV_NO_ENTRY;
+        }
+    }
     offsetptr = con->rc_offsets_array +
         (offsetentry_index*offset_len);
     READ_UNALIGNED_CK(dbg,targetoffset,Dwarf_Unsigned,

